      'productPreset.ceoChallenge.promptOverlay': '[CEO CHALLENGE - RUNTIME OVERLAY]\n\nInstruction runtime : challenger la strategie avec franchise, exposer les hypotheses fragiles, les angles morts, les risques et les compromis.\nLes attentes de sortie et signaux decisionnels sont injectes depuis le playbook canonique ; cet overlay n est pas une source UX/metier.\n\nConserve une analyse contradictoire, falsifiable et actionnable. Inclure une logique de validation observable et des criteres de pivot/kill lorsque pertinent.\n\n--- Contexte utilisateur ci-dessous ---',
      'founderInterrogation.title': 'Clarification (Founder Interrogation)',
